-- =====================================================================================
-- Snapshot stock mock for the Predictive Medicine Demand "Forecast from" date.
-- Generated by backend/scripts/generateSnapshotStockMock.js (seeded: same output every run).
-- Each medicine gets a restock history (a batch every 4-7 weeks, SNAP-<medicine>-<cycle>), every
-- consultation_dispensation / direct_dispensation row is pointed at the batch it was taken from, and the
-- current batches keep their stock and expiry (only created_at moves to the last restock dates), so today's
-- stock and forecast do not change. Back up first; the original mapping is in backend/scripts/snapshotStockMock.backup.json.
-- Run with: mysql --default-character-set=utf8mb4 -u root -p < seed_snapshot_stock_mock.sql
-- =====================================================================================
USE ClinicManagementSystem;
SET time_zone = '+08:00';
START TRANSACTION;

ON DUPLICATE KEY UPDATE medicine_id = VALUES(medicine_id), expiration_date = VALUES(expiration_date), current_stock = 0, remaining_volume = 0.00, created_at = VALUES(created_at);
ON DUPLICATE KEY UPDATE medicine_id = VALUES(medicine_id), expiration_date = VALUES(expiration_date), current_stock = 0, remaining_volume = 0.00, created_at = VALUES(created_at);

UPDATE medicine_inventory_batches SET created_at = '2026-10-08 07:30:00' WHERE batch_id = '61480fc3-075f-4bfe-a3ef-1fa88d316764';
