CREATE TEMPORARY TABLE tmp_snap_map (kind CHAR(1) NOT NULL, row_id VARCHAR(45) NOT NULL, batch_id VARCHAR(45) NOT NULL, PRIMARY KEY (kind, row_id));
UPDATE consultation_dispensation c JOIN tmp_snap_map t ON t.kind = 'C' AND t.row_id = c.consultation_dispense_id SET c.batch_id = t.batch_id;
UPDATE direct_dispensation d JOIN tmp_snap_map t ON t.kind = 'D' AND t.row_id = d.direct_dispense_id SET d.batch_id = t.batch_id;
DROP TEMPORARY TABLE tmp_snap_map;

-- old SNAP batches that are no longer in the plan (re-runs)
